                        window.mySimulation.t('insufficient_savings_warning'), 'warning'
                    );
                    return false;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = { period: period };

            if (period === 1) {
                var rent = this.RENT_BASE + (ds.events.roommateLeaves ? 40 : 0);
                ds.rentAdjustment = ds.events.roommateLeaves ? 40 : 0;
                var bonusIncome = ds.events.performanceBonus ? 50 : 0;
                ds.bonusReceived = ds.events.performanceBonus;

                var effectiveIncome = this.NET_INCOME + bonusIncome;
                var totalFixed = rent + this.GROCERIES + this.BUS + this.PHONE + this.PERSONAL_CARE;
                var totalExpenses = totalFixed + d.discretionaryLevel;
                var budgetBalance = effectiveIncome - totalExpenses - d.savingsAmount;

                var membershipFee = 0;
                if (d.savingsVehicle === 'cooperativa') {
                    membershipFee = 20;
                    ds.cooperativaFeePaid = true;
                }

                var actualFirstMonthSavings = Math.max(d.savingsAmount - membershipFee, 0);

                ds.savings = actualFirstMonthSavings;
                ds.savingsVehicle = d.savingsVehicle;
                ds.savingsRate = d.savingsAmount;

                var needsPercent = (totalFixed / effectiveIncome) * 100;
                var wantsPercent = (d.discretionaryLevel / effectiveIncome) * 100;
                var savingsPercent = (d.savingsAmount / effectiveIncome) * 100;

                var budgetScoreVal = 40;
                if (budgetBalance >= 0) budgetScoreVal += 10;
                if (d.savingsVehicle !== 'piggybank') budgetScoreVal += 10;
                if (savingsPercent >= 20) budgetScoreVal += 40;
                else if (savingsPercent >= 15) budgetScoreVal += 30;
                else if (savingsPercent >= 10) budgetScoreVal += 20;
                else if (savingsPercent >= 5) budgetScoreVal += 10;
                ds.budgetScore = Math.min(budgetScoreVal, 100);

                if (savingsPercent >= 20) ds.savingsRateScore = 100;
                else if (savingsPercent >= 15) ds.savingsRateScore = 85;
                else if (savingsPercent >= 10) ds.savingsRateScore = 70;
                else if (savingsPercent >= 5) ds.savingsRateScore = 50;
                else if (savingsPercent > 0) ds.savingsRateScore = 30;
                else ds.savingsRateScore = 0;

                ds.sfpScore = Math.round(
                    ds.budgetScore * 0.40 +
                    ds.savingsRateScore * 0.30 +
                    ds.creditAvoidanceScore * 0.20 +
                    ds.trapAvoidanceScore * 0.10
                );

                results.budgetBalance = Math.round(budgetBalance * 100) / 100;
                results.monthlySavings = actualFirstMonthSavings;
                results.totalSavings = ds.savings;
                results.sfpScore = ds.sfpScore;
                results.needsPercent = Math.round(needsPercent * 10) / 10;
                results.wantsPercent = Math.round(wantsPercent * 10) / 10;
                results.savingsPercent = Math.round(savingsPercent * 10) / 10;

                var rhtml = '';
                rhtml += '<strong>' + window.mySimulation.t('r1_income') + ':</strong> $' + effectiveIncome.toFixed(2);
                if (bonusIncome > 0) rhtml += ' <span style="color:#2e7d32">(+$50 ' + window.mySimulation.t('word_bonus') + ')</span>';
                rhtml += '<br>';
                rhtml += '<strong>' + window.mySimulation.t('r1_fixed') + ':</strong> $' + totalFixed.toFixed(2);
                if (ds.rentAdjustment > 0) rhtml += ' <span style="color:#c62828">(+$40 ' + window.mySimulation.t('word_rent') + ')</span>';
                rhtml += '<br>';
                rhtml += '<strong>' + window.mySimulation.t('r1_discretionary') + ':</strong> $' + d.discretionaryLevel.toFixed(2);
                rhtml += '<br>';
                rhtml += '<strong>' + window.mySimulation.t('r1_savings') + ':</strong> $' + d.savingsAmount.toFixed(2);
                if (membershipFee > 0) rhtml += ' <span style="color:#ff9800">(-$20 ' + window.mySimulation.t('r1_coop_fee') + ')</span>';
                rhtml += '<br>';
                rhtml += '<strong>' + window.mySimulation.t('r1_balance') + ':</strong> $' + budgetBalance.toFixed(2);
                rhtml += '<br><br>';
                rhtml += '<strong>' + window.mySimulation.t('r1_rule') + ':</strong><br>';

                var needsColor = needsPercent <= 55 ? '#2e7d32' : (needsPercent <= 65 ? '#ff9800' : '#c62828');
                var wantsColor = wantsPercent <= 30 ? '#2e7d32' : '#c62828';
                var savColor = savingsPercent >= 20 ? '#2e7d32' : (savingsPercent >= 10 ? '#ff9800' : '#c62828');

                rhtml += '<span style="color:' + needsColor + '">' + window.mySimulation.t('r1_needs') + ': ' + results.needsPercent + '%</span> <small>(meta: 50%)</small><br>';
                rhtml += '<span style="color:' + wantsColor + '">' + window.mySimulation.t('r1_wants') + ': ' + results.wantsPercent + '%</span> <small>(meta: 30%)</small><br>';
                rhtml += '<span style="color:' + savColor + '">' + window.mySimulation.t('r1_saving_pct') + ': ' + results.savingsPercent + '%</span> <small>(meta: 20%)</small>';

                var resultsEl = document.getElementById('resultsText');
                if (resultsEl) resultsEl.innerHTML = rhtml;
                var resultsPanel = document.getElementById('resultsPanel');
                if (resultsPanel) resultsPanel.style.display = 'block';

            } else if (period === 2) {
                var monthsPassed = 3;
                var annualRate = 0;
                if (ds.savingsVehicle === 'banco') annualRate = 0.02;
                else if (ds.savingsVehicle === 'cooperativa') annualRate = 0.045;

                var cooperativaFee = ds.cooperativaFeePaid ? 20 : 0;
                var totalSaved = ds.savingsRate * monthsPassed - cooperativaFee;
                if (totalSaved < 0) totalSaved = 0;

                var monthlyRate = annualRate / 12;
                var interest = totalSaved * monthlyRate * 1.5;
                interest = Math.round(interest * 100) / 100;
                ds.interestEarned = interest;
                ds.savings = Math.round((totalSaved + interest) * 100) / 100;

                var creditCost = 0;
                var speakerTotalOnCredit = 0;
                var speakerMonthlyPayment = 0;

                if (d.speakerDecision === 'credit') {
                    var principal = 200;
                    var mr = 0.24 / 12;
                    var pmt = principal * (mr * Math.pow(1 + mr, 12)) / (Math.pow(1 + mr, 12) - 1);
                    pmt = Math.round(pmt * 100) / 100;
                    speakerMonthlyPayment = pmt;
                    speakerTotalOnCredit = Math.round(pmt * 12 * 100) / 100;
                    creditCost = Math.round((speakerTotalOnCredit - principal) * 100) / 100;
                    ds.debt += speakerTotalOnCredit;
                    ds.monthlyPayment = pmt;
                    ds.totalCreditCost += creditCost;
                }

                if (d.creditCardActivation === 'yes') {
                    ds.creditCardActive = true;
                }

                ds.flashSalePurchased = false;
                if (ds.events.flashSale && ds.creditCardActive) {
                    ds.flashSalePurchased = true;
                    var fMr = 0.24 / 12;
                    var fPmt = 80 * (fMr * Math.pow(1 + fMr, 6)) / (Math.pow(1 + fMr, 6) - 1);
                    var fTotal = Math.round(fPmt * 6 * 100) / 100;
                    var fInterest = Math.round((fTotal - 80) * 100) / 100;
                    ds.debt += fTotal;
                    ds.totalCreditCost += fInterest;
                }

                if (d.cadenaParticipation === 'yes') {
                    ds.cadenaActive = true;
                    ds.cadenaAmount = 50;
                }

                if (ds.totalCreditCost === 0) ds.creditAvoidanceScore = 100;
                else if (ds.totalCreditCost <= 30) ds.creditAvoidanceScore = 60;
                else ds.creditAvoidanceScore = 30;

                ds.sfpScore = Math.round(
                    ds.budgetScore * 0.40 +
                    ds.savingsRateScore * 0.30 +
                    ds.creditAvoidanceScore * 0.20 +
                    ds.trapAvoidanceScore * 0.10
                );

                results.budgetBalance = Math.round((this.NET_INCOME - this.FIXED_TOTAL - ds.rentAdjustment - 40 - ds.savingsRate - (ds.monthlyPayment || 0) - (ds.cadenaActive ? 50 : 0)) * 100) / 100;
                results.monthlySavings = ds.savingsRate;
                results.totalSavings = ds.savings;
                results.sfpScore = ds.sfpScore;
                results.creditCost = creditCost;
                results.speakerTotalCost = speakerTotalOnCredit;

                var rhtml2 = '';
                rhtml2 += '<strong>' + window.mySimulation.t('r2_savings_accumulated') + ':</strong> $' + ds.savings.toFixed(2);
                if (ds.interestEarned > 0) rhtml2 += ' <span style="color:#2e7d32">(+$' + ds.interestEarned.toFixed(2) + ' ' + window.mySimulation.t('r2_interest') + ')</span>';
                rhtml2 += '<br><br>';

                if (d.speakerDecision === 'credit') {
                    rhtml2 += '<strong>🔊 ' + window.mySimulation.t('r2_speaker_credit') + '</strong><br>';
                    rhtml2 += window.mySimulation.t('r2_monthly_payment') + ': $' + speakerMonthlyPayment.toFixed(2) + ' ' + window.mySimulation.t('r2_x12') + '<br>';
                    rhtml2 += window.mySimulation.t('r2_total_paid') + ': $' + speakerTotalOnCredit.toFixed(2) + '<br>';
                    rhtml2 += '<span style="color:#c62828; font-weight:bold">' + window.mySimulation.t('r2_credit_cost') + ': $' + creditCost.toFixed(2) + '</span><br>';
                    var hoursOfWork = Math.round(creditCost / 3.13 * 10) / 10;
                    rhtml2 += '<small>' + window.mySimulation.t('r2_hours_work') + ': ' + hoursOfWork + ' ' + window.mySimulation.t('r2_hours') + '</small><br>';
                } else if (d.speakerDecision === 'save') {
                    rhtml2 += '<span style="color:#2e7d32">✅ ' + window.mySimulation.t('r2_speaker_save') + '</span><br>';
                } else {
                    rhtml2 += '<span style="color:#1565c0">💰 ' + window.mySimulation.t('r2_speaker_skip') + '</span><br>';
                }
                rhtml2 += '<br>';

                if (ds.flashSalePurchased) {
                    rhtml2 += '<span style="color:#c62828">👟 ' + window.mySimulation.t('r2_flash_sale_bought') + '</span><br><br>';
                }

                if (ds.creditCardActive) {
                    rhtml2 += '💳 ' + window.mySimulation.t('r2_card_active') + '<br>';
                }
                if (ds.cadenaActive) {
                    rhtml2 += '🔗 ' + window.mySimulation.t('r2_cadena_active') + '<br>';
                }

                var resultsEl2 = document.getElementById('resultsText');
                if (resultsEl2) resultsEl2.innerHTML = rhtml2;
                var resultsPanel2 = document.getElementById('resultsPanel');
                if (resultsPanel2) resultsPanel2.style.display = 'block';

            } else if (period === 3) {
                var additionalSavings = ds.savingsRate * 3;
                ds.savings += additionalSavings;

                if (ds.cadenaActive) {
                    ds.savings += ds.cadenaAmount * 3;
                }

                var vehicleRate = 0;
                if (ds.savingsVehicle === 'banco') vehicleRate = 0.02;
                else if (ds.savingsVehicle === 'cooperativa') vehicleRate = 0.045;
                var addedInterest = ds.savings * (vehicleRate / 12) * 3;
                ds.savings += addedInterest;
                ds.savings = Math.round(ds.savings * 100) / 100;

                var emergencyCost = 85;
                var emergencyMethod = d.emergencyHandling;
                var emergencyCreditCost = 0;

                if (emergencyMethod === 'savings') {
                    ds.savings = Math.max(ds.savings - emergencyCost, 0);
                } else if (emergencyMethod === 'credit') {
                    var eMr = 0.24 / 12;
                    var ePmt = emergencyCost * (eMr * Math.pow(1 + eMr, 6)) / (Math.pow(1 + eMr, 6) - 1);
                    var eTotal = Math.round(ePmt * 6 * 100) / 100;
                    emergencyCreditCost = Math.round((eTotal - emergencyCost) * 100) / 100;
                    ds.debt += eTotal;
                    ds.totalCreditCost += emergencyCreditCost;
                }

                if (d.informalInvestment === 'yes') {
                    ds.pyramidLoss = 100;
                    ds.savings = Math.max(ds.savings - 100, 0);
                }

                var trapScore = 100;
                if (d.informalInvestment === 'yes') trapScore -= 50;
                if (ds.creditCardActive && (d.speakerDecision === 'credit' || ds.flashSalePurchased)) trapScore -= 25;
                ds.trapAvoidanceScore = Math.max(trapScore, 0);

                if (ds.totalCreditCost === 0) ds.creditAvoidanceScore = 100;
                else if (ds.totalCreditCost <= 30) ds.creditAvoidanceScore = 60;
                else if (ds.totalCreditCost <= 50) ds.creditAvoidanceScore = 40;
                else ds.creditAvoidanceScore = 20;

                var overallSavingsRate = (ds.savings / (this.NET_INCOME * 6)) * 100;
                if (overallSavingsRate >= 15) ds.savingsRateScore = 100;
                else if (overallSavingsRate >= 10) ds.savingsRateScore = 80;
                else if (overallSavingsRate >= 5) ds.savingsRateScore = 60;
                else if (overallSavingsRate > 0) ds.savingsRateScore = 30;
                else ds.savingsRateScore = 0;

                ds.sfpScore = Math.round(
                    ds.budgetScore * 0.40 +
                    ds.savingsRateScore * 0.30 +
                    ds.creditAvoidanceScore * 0.20 +
                    ds.trapAvoidanceScore * 0.10
                );

                results.budgetBalance = Math.round((this.NET_INCOME - this.FIXED_TOTAL - ds.rentAdjustment - 40 - ds.savingsRate) * 100) / 100;
                results.monthlySavings = ds.savingsRate;
                results.totalSavings = ds.savings;
                results.sfpScore = ds.sfpScore;

                var commitment = d.futureCommitment;
                var years = 47;
                var annReturn = 0.05;
                var mReturn = annReturn / 12;
                var totalMonths = years * 12;

                var fv0 = 0;
                var fv45 = 45 * (Math.pow(1 + mReturn, totalMonths) - 1) / mReturn;
                var fv90 = 90 * (Math.pow(1 + mReturn, totalMonths) - 1) / mReturn;
                var months28 = 37 * 12;
                var fv45late = 45 * (Math.pow(1 + mReturn, months28) - 1) / mReturn;

                fv45 = Math.round(fv45);
                fv90 = Math.round(fv90);
                fv45late = Math.round(fv45late);

                var rhtml3 = '';
                rhtml3 += '<strong>📱 ' + window.mySimulation.t('r3_emergency_title') + '</strong><br>';
                if (emergencyMethod === 'savings') {
                    rhtml3 += '<span style="color:#2e7d32">✅ ' + window.mySimulation.t('r3_used_savings') + '</span><br>';
                } else if (emergencyMethod === 'credit') {
                    rhtml3 += '<span style="color:#c62828">💳 ' + window.mySimulation.t('r3_used_credit') + ' (+$' + emergencyCreditCost.toFixed(2) + ' ' + window.mySimulation.t('r2_interest') + ')</span><br>';
                } else {
                    rhtml3 += '<span style="color:#ff9800">👨‍👩‍👧 ' + window.mySimulation.t('r3_used_family') + '</span><br>';
                }
                rhtml3 += '<br>';

                if (d.informalInvestment === 'yes') {
                    rhtml3 += '<span style="color:#c62828; font-weight:bold">🚨 ' + window.mySimulation.t('r3_pyramid_loss') + '</span><br><br>';
                } else {
                    rhtml3 += '<span style="color:#2e7d32; font-weight:bold">🛡️ ' + window.mySimulation.t('r3_pyramid_avoided') + '</span><br><br>';
                }

                rhtml3 += '<strong>' + window.mySimulation.t('r3_final_savings') + ':</strong> $' + ds.savings.toFixed(2) + '<br>';
                rhtml3 += '<strong>' + window.mySimulation.t('r3_total_debt') + ':</strong> <span style="color:' + (ds.debt > 0 ? '#c62828' : '#2e7d32') + '">$' + ds.debt.toFixed(2) + '</span><br>';
                rhtml3 += '<strong>' + window.mySimulation.t('r3_sfp_final') + ':</strong> <span style="font-size:1.3em; font-weight:bold; color:' + (ds.sfpScore >= 70 ? '#2e7d32' : (ds.sfpScore >= 40 ? '#ff9800' : '#c62828')) + '">' + ds.sfpScore + '/100</span>';

                var resultsEl3 = document.getElementById('resultsText');
                if (resultsEl3) resultsEl3.innerHTML = rhtml3;
                var resultsPanel3 = document.getElementById('resultsPanel');
                if (resultsPanel3) resultsPanel3.style.display = 'block';

                var phtml = '';
                phtml += '<p>' + window.mySimulation.t('proj_intro') + '</p>';
                phtml += '<table class="table table-sm table-bordered"><thead class="thead-dark"><tr>';
                phtml += '<th>' + window.mySimulation.t('proj_scenario') + '</th>';
                phtml += '<th>' + window.mySimulation.t('proj_monthly') + '</th>';
                phtml += '<th>' + window.mySimulation.t('proj_at_65') + '</th>';
                phtml += '</tr></thead><tbody>';
                phtml += '<tr><td>' + window.mySimulation.t('proj_none') + '</td><td>$0</td><td style="color:#c62828">$0</td></tr>';
                phtml += '<tr style="background:#e8f5e9"><td>' + window.mySimulation.t('proj_moderate') + '</td><td>$45</td><td style="color:#2e7d32; font-weight:bold">$' + fv45.toLocaleString() + '</td></tr>';
                phtml += '<tr style="background:#c8e6c9"><td>' + window.mySimulation.t('proj_aggressive') + '</td><td>$90</td><td style="color:#2e7d32; font-weight:bold">$' + fv90.toLocaleString() + '</td></tr>';
                phtml += '<tr style="background:#fff3e0"><td>' + window.mySimulation.t('proj_late_start') + '</td><td>$45</td><td style="color:#ff9800">$' + fv45late.toLocaleString() + '</td></tr>';
                phtml += '</tbody></table>';
                phtml += '<small style="color:#666">' + window.mySimulation.t('proj_note') + '</small>';

                var projEl = document.getElementById('projectionText');
                if (projEl) projEl.innerHTML = phtml;
                var projPanel = document.getElementById('projectionPanel');
                if (projPanel) projPanel.style.display = 'block';
            }

            ds.sfpHistory.push(ds.sfpScore);
            ds.savingsHistory.push(ds.savings);

            // Persist grade for server + reporting layer (reads domainState.performance.overallScore)
            var perf = this._persistPerformance(state);
            results.overallScore = perf.overallScore;
            results.score = perf.score;
            results.performance = perf.tier;

            var self = this;
            if (period < 3) {
                // Advance to the next round; keep this round's results visible so the
                // student can read the consequence of their decision (preserveResults=true).
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: period + 1, domainState: ds }, true);
                }, 1400);
            }
            // Final period (period === 3): do NOT auto-advance — leave results + projection
            // on screen; the framework renders the debrief via formatCompletionMessage().

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('savingsDisplay', 'domainState.savings',
                (v) => '$' + (v || 0).toFixed(2));
            uiManager.bind('debtDisplay', 'domainState.debt',
                (v) => '$' + (v || 0).toFixed(2));
            uiManager.bind('sfpDisplay', 'domainState.sfpScore',
                (v) => v > 0 ? v + '/100' : '--');
        }

        getChartConfig() {
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };
            return {
                sfpChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_sfp_label'),
                            data: [],
                            backgroundColor: [
                                'rgba(46,125,50,0.7)',
                                'rgba(21,101,192,0.7)',
                                'rgba(123,31,162,0.7)'
                            ],
                            borderColor: [
                                '#2e7d32',
                                '#1565c0',
                                '#7b1fa2'
                            ],
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_sfp_title') }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                },
                savingsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_savings_label'),
                            data: [],
                            borderColor: '#1565c0',
                            backgroundColor: 'rgba(21,101,192,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_savings_title') }
                        },
                        scales: {
                            y: { beginAtZero: true }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.sfpHistory.map(function(_, i) {
                return 'R' + (i + 1);
            });
            return {
                sfpChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.sfpHistory }]
                },
                savingsChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.savingsHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var lastRecord = history[history.length - 1];
            var lds = lastRecord.domainState || {};
            var lres = lastRecord.results || {};

            // Prefer the persisted grade written by _persistPerformance; fall back to sfpScore.
            var sfp = (lds.performance && typeof lds.performance.overallScore === 'number')
                ? lds.performance.overallScore
                : (typeof lds.sfpScore === 'number' ? lds.sfpScore : (lres.sfpScore || 0));
            var overallScore = Math.max(0, Math.min(100, Math.round(sfp)));

            var totalSavings = (typeof lds.savings === 'number') ? lds.savings : (lres.totalSavings || 0);
            var debt = (typeof lds.debt === 'number') ? lds.debt : 0;

            var tier = this._tierFrom(overallScore);

            var insights = [];
            if (overallScore >= 70) {
                insights.push(window.mySimulation.t('summary_good_health'));
            } else {
                insights.push(window.mySimulation.t('summary_improve'));
            }
            if (totalSavings > 200) {
                insights.push(window.mySimulation.t('summary_good_savings'));
            }
            if (debt > 0) {
                insights.push(window.mySimulation.t('summary_has_debt'));
            }

            return {
                overallScore: overallScore,
                score: overallScore,
                sfpScore: overallScore,
                grade: this._letterFrom(overallScore),
                performance: tier,
                performanceTier: tier,
                performanceLabel: this._tierLabel(tier),
                totalSavings: totalSavings,
                debt: debt,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };
            summary = summary || {};
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : 0;
            var label = summary.performanceLabel || this._tierLabel(summary.performance || this._tierFrom(score));
            var savings = (typeof summary.totalSavings === 'number') ? summary.totalSavings : 0;
            var debt = (typeof summary.debt === 'number') ? summary.debt : 0;
            var scoreColor = score >= 70 ? '#2e7d32' : (score >= 40 ? '#ff9800' : '#c62828');

            var html = '';
            html += '<div class="mps-sim-cm">';
            html += '<div class="mps-sim-cm-title">' + t('cm_title') + '</div>';
            html += '<div class="mps-sim-cm-score" style="color:' + scoreColor + '">' + score + '<span class="mps-sim-cm-score-max">/100</span></div>';
            html += '<div class="mps-sim-cm-verdict">' + label + '</div>';
            html += '<div class="mps-sim-cm-kpis">';
            html += '<div class="mps-sim-cm-kpi"><span class="mps-sim-cm-kpi-label">' + t('cm_savings') + '</span><span class="mps-sim-cm-kpi-val">$' + savings.toFixed(2) + '</span></div>';
            html += '<div class="mps-sim-cm-kpi"><span class="mps-sim-cm-kpi-label">' + t('cm_debt') + '</span><span class="mps-sim-cm-kpi-val" style="color:' + (debt > 0 ? '#c62828' : '#2e7d32') + '">$' + debt.toFixed(2) + '</span></div>';
            html += '<div class="mps-sim-cm-kpi"><span class="mps-sim-cm-kpi-label">' + t('cm_health') + '</span><span class="mps-sim-cm-kpi-val">' + score + '/100</span></div>';
            html += '</div>';
            var ins = summary.insights || [];
            if (ins.length) {
                html += '<ul class="mps-sim-cm-insights">';
                for (var i = 0; i < ins.length; i++) { html += '<li>' + ins[i] + '</li>'; }
                html += '</ul>';
            }
            html += '<div class="mps-sim-cm-foot">' + t('cm_footer') + '</div>';
            html += '</div>';

            // Render into the sim's own completion slot so the debrief is visible even if the
            // host framework does not surface the returned string.
            var slot = document.getElementById('mpsCompletionPanel');
            if (slot) { slot.innerHTML = html; slot.style.display = 'block'; }
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            var period = state.currentPeriod;
            if (period === 1 && results.savingsPercent !== undefined && results.savingsPercent < 10) {
                return window.mySimulation.t('hint_low_savings');
            }
            if (period === 2 && state.domainState.totalCreditCost > 0) {
                return window.mySimulation.t('hint_credit_cost');
            }
            if (period === 3 && state.domainState.pyramidLoss > 0) {
                return window.mySimulation.t('hint_pyramid');
            }
            if (period === 1 && results.savingsPercent >= 20) {
                return window.mySimulation.t('hint_great_savings');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.budgetBalance', label: 'Balance', i18nKey: 'col_balance', formatter: (v) => '$' + (v || 0).toFixed(2) },
                { key: 'results.monthlySavings', label: 'Ahorro Mensual', i18nKey: 'col_monthly_savings', formatter: (v) => '$' + (v || 0).toFixed(2) },
                { key: 'results.totalSavings', label: 'Ahorros Totales', i18nKey: 'col_total_savings', formatter: (v) => '$' + (v || 0).toFixed(2) },
                { key: 'results.sfpScore', label: 'SFP', i18nKey: 'col_sfp', formatter: (v) => (v || 0) + '/100' }
            ];
        }

